/** Disposable emulator only. The fixture contains no personal ledger data. */
final class CategoryOrderChecks {
 static final String[] EXPENSE={"교통","기타","쇼핑","식비","출장비","카페"};
 static String data(Context c){List<String> out=new ArrayList<>();try(LedgerDb db=new LedgerDb(c)){for(String table:new String[]{"entries","feature_state"})try(Cursor q=db.getReadableDatabase().rawQuery("SELECT rowid,* FROM "+table+" ORDER BY rowid",null)){while(q.moveToNext()){StringJoiner line=new StringJoiner("|");for(int i=0;i<q.getColumnCount();i++)line.add(q.getString(i));out.add(table+":"+line);}}}return String.join("\n",out);}
 static String prefs(Context c){List<String> out=new ArrayList<>();for(String name:new String[]{"app_preferences","category_choices","backup_status"}){TreeMap<String,Object> map=new TreeMap<>();for(Map.Entry<String,?> e:c.getSharedPreferences(name,0).getAll().entrySet())map.put(e.getKey(),e.getValue() instanceof Set?new TreeSet<>((Set<String>)e.getValue()):e.getValue());out.add(name+":"+map);}return String.join("\n",out);}
 static void fixture(Context c){try(LedgerDb db=CategoryChecks.fresh(c)){CategoryStore store=new CategoryStore(c);for(String n:EXPENSE)store.remember("지출",n);for(String n:new String[]{"급여","부수입"})store.remember("수입",n);for(String n:new String[]{"예금","적금"})store.remember("저축",n);for(String n:new String[]{"ETF","주식"})store.remember("투자",n);db.save(new Ledger.Entry("order-record","2026-11-01","14:05:36","지출",100,"식비","합성 기록 보존",0),false);PlanningData plan=new PlanningData();plan.put(new PlanningData.Limit("*","지출","",1000));plan.selectLivingCategories(Arrays.asList("식비","카페"));plan.put(new PlanningData.Favorite("order-favorite","합성 카페","지출",50,"카페",""));db.savePlanning(plan);CategoryMigration.run(c,db);}c.getSharedPreferences("category_choices",0).edit().putString("unrelated","preserve opaque").commit();c.getSharedPreferences("backup_status",0).edit().clear().putLong("first_seen",12340).putLong("last_full",12345).commit();}
 static List<String> choices(Context c,String type){try(LedgerDb db=new LedgerDb(c)){return new CategoryStore(c).choices(type,db.all(),db.planning());}}
 static void before(DeviceChecks t)throws Exception{
  Context c=t.getTargetContext();t.eq("0.8.13",c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName);fixture(c);
  try(LedgerDb db=new LedgerDb(c)){CategoryStore store=new CategoryStore(c);for(String[] p:new String[][]{{"지출","식비"},{"수입","부수입"},{"저축","적금"},{"투자","주식"}}){while(store.choices(p[0],db.all(),db.planning()).indexOf(p[1])>0)store.move(p[0],p[1],-1,db.all(),db.planning());}store.remember("지출","보존 숨김");store.delete("지출","보존 숨김");new AppPreferences(c).dark(true);}
  MainActivity app=StartupChecks.start(t,false);StartupChecks.close(t,app);String text=data(c)+"\n"+prefs(c);try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(c.getExternalFilesDir(null),"category-order-before.txt")),java.nio.charset.StandardCharsets.UTF_8)){w.write(text);}t.eq("식비",choices(c,"지출").get(0));
 }
 static void upgraded(DeviceChecks t)throws Exception{
  Context c=t.getTargetContext();String before;try(InputStream in=new FileInputStream(new File(c.getExternalFilesDir(null),"category-order-before.txt"));ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);before=new String(b.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}MainActivity app=StartupChecks.start(t,false);StartupChecks.close(t,app);t.eq(before,data(c)+"\n"+prefs(c));t.eq("0.8.14",c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName);t.eq(28,c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode);try(LedgerDb db=new LedgerDb(c)){t.eq(5,db.getReadableDatabase().getVersion());t.eq("14:05:36",db.all().get(0).time);}for(String[] p:new String[][]{{"지출","식비"},{"수입","부수입"},{"저축","적금"},{"투자","주식"}})t.eq(p[1],choices(c,p[0]).get(0));t.eq(true,new CategoryStore(c).deleted("지출").contains("보존 숨김"));
 }
 static void click(DeviceChecks t,String desc){t.runOnMainSync(()->t.windowDesc(desc).performClick());t.waitForIdleSync();}
 static List<String> visible(DeviceChecks t){ScrollView scroll=(ScrollView)t.windowDesc("상세 분류 목록");ViewGroup rows=(ViewGroup)scroll.getChildAt(0);List<String> result=new ArrayList<>();for(int i=0;i<rows.getChildCount();i++){Object tag=rows.getChildAt(i).getTag();if(tag!=null)result.add(tag.toString());}return result;}
 static List<String> chooser(DeviceChecks t){ListView list=(ListView)t.windowView(ListView.class);List<String> out=new ArrayList<>();for(int i=0;i<list.getAdapter().getCount();i++)out.add(list.getAdapter().getItem(i).toString());return out;}
 static void open(DeviceChecks t,MainActivity app)throws Exception{t.navigate(app,6);click(t,"상세 분류 관리");}
 static void add(DeviceChecks t,String name)throws Exception{click(t,"관리에서 상세 분류 추가");t.planField("상세 분류 이름",name);t.clickText("추가");t.waitForIdleSync();}
 static View rowOf(DeviceChecks t,String name){ViewGroup rows=(ViewGroup)((ScrollView)t.windowDesc("상세 분류 목록")).getChildAt(0);for(int i=0;i<rows.getChildCount();i++)if(name.equals(rows.getChildAt(i).getTag()))return rows.getChildAt(i);throw new AssertionError("row "+name);}
 static boolean hasAction(DeviceChecks t,String name,int id){final boolean[] found={false};t.runOnMainSync(()->{android.view.accessibility.AccessibilityNodeInfo info=rowOf(t,name).createAccessibilityNodeInfo();for(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction a:info.getActionList())if(a.getId()==id)found[0]=true;});return found[0];}
 static void moveUp(DeviceChecks t,String name){t.runOnMainSync(()->rowOf(t,name).performAccessibilityAction(CategoryDrag.ACTION_MOVE_UP,null));t.waitForIdleSync();}
 /** Real drag: touch the ≡ handle, move by whole rows, release. Waits for the settle animation. */
 static void drag(DeviceChecks t,String name,int rowsDelta)throws Exception{
  View row=rowOf(t,name);int[] at=new int[2];t.runOnMainSync(()->row.getLocationOnScreen(at));float h=row.getHeight(),x=at[0]+10*row.getResources().getDisplayMetrics().density,y=at[1]+h/2f,target=y+(rowsDelta+Math.signum(rowsDelta)*.25f)*h;long down=android.os.SystemClock.uptimeMillis();
  CategoryDragChecks.pointer(t,down,MotionEvent.ACTION_DOWN,x,y);for(int i=1;i<=10;i++){Thread.sleep(16);CategoryDragChecks.pointer(t,down,MotionEvent.ACTION_MOVE,x,y+(target-y)*i/10f);}CategoryDragChecks.pointer(t,down,MotionEvent.ACTION_UP,x,target);Thread.sleep(400);t.waitForIdleSync();
 }
 static void first(DeviceChecks t,String type,String name){for(int i=0;i<30&&visible(t).indexOf(name)>0;i++)moveUp(t,name);t.eq(name,visible(t).get(0));}
 static void run(DeviceChecks t)throws Exception{
  Context emptyContext=t.getTargetContext();try(LedgerDb empty=CategoryChecks.fresh(emptyContext)){}MainActivity emptyApp=StartupChecks.start(t,false);open(t,emptyApp);t.eq(Collections.emptyList(),visible(t));add(t,"처음 추가");t.eq(Arrays.asList("처음 추가"),visible(t));t.eq(false,hasAction(t,"처음 추가",CategoryDrag.ACTION_MOVE_UP));t.eq(false,hasAction(t,"처음 추가",CategoryDrag.ACTION_MOVE_DOWN));t.clickText("닫기");t.waitForIdleSync();StartupChecks.close(t,emptyApp);
  CategoryStore referenceStore=new CategoryStore(emptyContext);referenceStore.remember("지출","간식");referenceStore.move("지출","처음 추가",-1,Collections.emptyList(),new PlanningData());List<Ledger.Entry> references=Arrays.asList(new Ledger.Entry("reference-only","2026-11-01","지출",1,"엑셀 참조 분류","",0));referenceStore.remember("지출","가족",references,new PlanningData());List<String> referenceOrder=referenceStore.choices("지출",references,new PlanningData());t.eq(Arrays.asList("처음 추가","간식","엑셀 참조 분류","가족"),referenceOrder);
  Context c=t.getTargetContext();fixture(c);boolean dark=t.mode.equals("orderdark");new AppPreferences(c).dark(dark);MainActivity app=StartupChecks.start(t,false);String original=data(c);String appPrefs=c.getSharedPreferences("app_preferences",0).getAll().toString();open(t,app);t.eq(Arrays.asList(EXPENSE),visible(t));
  t.eq(false,hasAction(t,"교통",CategoryDrag.ACTION_MOVE_UP));t.eq(true,hasAction(t,"교통",CategoryDrag.ACTION_MOVE_DOWN));t.eq(false,hasAction(t,"카페",CategoryDrag.ACTION_MOVE_DOWN));t.eq(true,hasAction(t,"카페",CategoryDrag.ACTION_MOVE_UP));
  drag(t,"카페",-3);t.eq(Arrays.asList("교통","기타","카페","쇼핑","식비","출장비"),visible(t));t.eq(visible(t),choices(c,"지출"));drag(t,"카페",3);t.eq(Arrays.asList(EXPENSE),visible(t));drag(t,"교통",0);t.eq(Arrays.asList(EXPENSE),visible(t));t.eq(original,data(c));
  first(t,"지출","식비");List<String> expense=visible(t);t.eq(expense,choices(c,"지출"));
  add(t,"간식");t.eq("간식",visible(t).get(visible(t).size()-1));add(t,"가족");t.eq("가족",visible(t).get(visible(t).size()-1));int count=visible(t).size();add(t,"\u00a0간식\u3000");t.eq(count,visible(t).size());
  click(t,"관리에서 상세 분류 추가");t.planField("상세 분류 이름"," ");t.clickText("추가");t.waitForIdleSync();t.eq(true,((EditText)t.windowDesc("상세 분류 이름")).getError()!=null);t.clickText("취소");t.waitForIdleSync();t.eq(count,visible(t).size());
  for(String[] pair:new String[][]{{"수입","부수입"},{"저축","적금"},{"투자","주식"}}){click(t,pair[0]+" 상세 분류 관리");first(t,pair[0],pair[1]);t.eq(visible(t),choices(c,pair[0]));}
  t.eq(choices(c,"저축"),choices(c,"저축회수"));click(t,"지출 상세 분류 관리");t.eq("식비",visible(t).get(0));
  click(t,"지출 식비 상세 분류 삭제");t.eq(false,visible(t).contains("식비"));t.eq(original,data(c));t.clickText("삭제한 상세 분류 복원");t.waitForIdleSync();t.clickText("식비");t.waitForIdleSync();t.eq("식비",visible(t).get(0));
  add(t,"아주긴상세분류이름가나다라마바사아자차카타파하가나다라마바");t.screenshot(c,"category-order-long-"+dark);List<String> wanted=visible(t);t.eq(wanted,choices(c,"지출"));t.clickText("닫기");t.waitForIdleSync();StartupChecks.close(t,app);
  // A fresh activity/store must read exactly the saved order, without rewriting ledger/plans.
  app=StartupChecks.start(t,false);open(t,app);t.eq(wanted,visible(t));t.eq(original,data(c));t.screenshot(c,"category-order-"+dark);t.clickText("닫기");t.waitForIdleSync();
  final MainActivity current=app;t.runOnMainSync(()->{try{DeviceChecks.invoke(current,"newEntry",new Class[]{String.class},"지출");}catch(Exception e){throw new RuntimeException(e);}});t.waitForIdleSync();t.enterAmount("100","지출");t.clickText("상세 분류 선택");t.waitForIdleSync();t.eq(wanted,chooser(t));t.screenshot(c,"category-order-picker-"+dark);t.clickText("식비");t.waitForIdleSync();t.eq("식비",((EditText)t.windowDesc("새 기록 상세 분류")).getText().toString());t.clickText("취소");t.waitForIdleSync();
  t.runOnMainSync(()->{try{DeviceChecks.invoke(current,"limitEditor",new Class[]{PlanningData.Limit.class,String.class},null,"지출");}catch(Exception e){throw new RuntimeException(e);}});t.waitForIdleSync();click(t,"상세 분류 (비우면 전체) 선택");t.eq(wanted,chooser(t));t.clickText("취소");t.waitForIdleSync();t.clickText("취소");t.waitForIdleSync();
  t.eq(original,data(c));t.eq("preserve opaque",c.getSharedPreferences("category_choices",0).getString("unrelated",""));t.eq(appPrefs,c.getSharedPreferences("app_preferences",0).getAll().toString());
  // A damaged order setting falls back safely and is never silently overwritten by reading.
  String good=c.getSharedPreferences("category_choices",0).getString("order_지출","");c.getSharedPreferences("category_choices",0).edit().putString("order_지출","broken").commit();List<String> sorted=choices(c,"지출");t.eq(true,sorted.contains("식비"));t.eq("broken",c.getSharedPreferences("category_choices",0).getString("order_지출",""));c.getSharedPreferences("category_choices",0).edit().putInt("order_지출",1).commit();t.eq(sorted,choices(c,"지출"));t.eq(1,c.getSharedPreferences("category_choices",0).getInt("order_지출",0));c.getSharedPreferences("category_choices",0).edit().putString("order_지출",good).commit();t.eq(wanted,choices(c,"지출"));
  StartupChecks.close(t,app);
  try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(c.getExternalFilesDir(null),"category-order-after.txt")),java.nio.charset.StandardCharsets.UTF_8)){w.write(data(c)+"\n"+prefs(c));}
 }
 static void reopened(DeviceChecks t)throws Exception{Context c=t.getTargetContext();String before;try(InputStream in=new FileInputStream(new File(c.getExternalFilesDir(null),"category-order-after.txt"));ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);before=new String(b.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}MainActivity app=StartupChecks.start(t,false);t.eq(5,UserGuideChecks.get(app,"tab"));t.eq(before,data(c)+"\n"+prefs(c));t.eq("식비",choices(c,"지출").get(0));t.eq("부수입",choices(c,"수입").get(0));t.eq("적금",choices(c,"저축").get(0));t.eq("주식",choices(c,"투자").get(0));open(t,app);t.eq(choices(c,"지출"),visible(t));t.clickText("닫기");t.waitForIdleSync();StartupChecks.close(t,app);}
}
